    getParentLinkedStudentIds(supabase, sessionUser.id),
    getStudentSelfId(supabase, sessionUser.id),
    getUnreadNotificationCount(supabase, sessionUser.id),
    loadOrganizationBranding(supabase),
  ]);

  // A.1 — permission gate only (linkage is data scope, not an alternate entry path).
  if (!isParent && !isStudent) {
    redirect("/apply/portal");
  }

  const mode = isStudent && !isParent ? "student" : "parent";

  let students: { id: string; first_name: string; last_name: string }[] = [];
  if (studentIds.length) {
    const { data } = await supabase
      .from("students")
      .select("id, first_name, last_name")
      .in("id", studentIds);
    students = data ?? [];
  }

  return (
    <PortalShell
      userEmail={sessionUser.email}
      mode={mode}
      students={students}
      unreadNotifications={unread}
      productName={branding.productName}
    >
      {children}
    </PortalShell>
  );
}

"use client";

import Link from "next/link";
import { useTransition } from "react";
import {
  getActiveOrderedPipelineStages,
  pipelineStageColor,
  pipelineStageLabel,
  resolvePipelineStageFromLeadStage,
} from "@/lib/admissions/registry";
import { updateCaseStage } from "@/lib/admissions/case/actions";
import { buildAdmissionsCaseHref } from "@/lib/admissions/profile/href";
import { LEAD_STAGES, type LeadStageValue } from "@/lib/constants/admissions";
import { programLabel } from "@/lib/constants/programs";
import {
  daysInCurrentStage,
  pipelineAgingClasses,
  pipelineAgingDotClass,
} from "@/lib/admissions/workflow";
import type { AdmissionLead } from "@/lib/admissions/queries";

interface AdmissionsPipelineBoardProps {
  leads: AdmissionLead[];
}

/** OS pipeline board — groups leads by canonical pipeline stage. */
export function AdmissionsPipelineBoard({ leads }: AdmissionsPipelineBoardProps) {
  const [, startTransition] = useTransition();
  const stages = getActiveOrderedPipelineStages();

  function handleStageChange(leadId: string, stage: LeadStageValue) {
    startTransition(async () => {
      await updateCaseStage(leadId, stage);
    });
  }

  return (
    <div className="flex gap-4 overflow-x-auto pb-4">
      {stages.map((stage) => {
        const stageLeads = leads.filter(
          (lead) => resolvePipelineStageFromLeadStage(lead.lead_stage) === stage.key
        );
        return (
          <div
            key={stage.key}
            className="flex w-72 shrink-0 flex-col rounded-2xl border border-slate-200/80 bg-slate-50"
          >
            <div className="border-b border-slate-200/80 px-4 py-3">
              <div className="flex items-center justify-between">
                <span className={`rounded-full px-2 py-0.5 text-xs font-medium ${stage.color}`}>
                  {stage.label}
                </span>
                <span className="text-xs font-medium text-slate-500">{stageLeads.length}</span>
              </div>
            </div>
            <div className="flex flex-1 flex-col gap-2 p-3">
              {stageLeads.map((lead) => {
                const days = daysInCurrentStage(lead.stage_entered_at);
                return (
                  <div
                    key={lead.id}
                    className="rounded-xl border border-slate-200/80 bg-white p-3 shadow-sm"
                  >
                    <div className="flex items-start justify-between gap-2">
                      <Link
                        href={buildAdmissionsCaseHref(lead.id)}
                        className="font-medium text-slate-900 hover:text-brand-600"
                      >
                        {lead.first_name} {lead.last_name}
                      </Link>
                      <span
                        className={`mt-1 h-2 w-2 shrink-0 rounded-full ${pipelineAgingDotClass(days)}`}
                        title={`${days} days in stage`}
                      />
                    </div>
                    <span
                      className={`mt-1 inline-block rounded-full border px-2 py-0.5 text-xs font-medium ${pipelineAgingClasses(days)}`}
                    >
                      {days}d
                    </span>
                    {lead.program && (
                      <p className="mt-1 text-xs text-slate-500">{programLabel(lead.program)}</p>
                    )}
                    <p className="mt-1 text-xs text-slate-400 capitalize">
                      {pipelineStageLabel(resolvePipelineStageFromLeadStage(lead.lead_stage) ?? stage.key)}
                    </p>
                    <select
                      value={lead.lead_stage}
                      onChange={(e) => handleStageChange(lead.id, e.target.value as LeadStageValue)}
                      className="mt-2 w-full rounded-lg border border-slate-200 px-2 py-1 text-xs text-slate-700"
                    >
                      {LEAD_STAGES.map((s) => (
                        <option key={s.value} value={s.value}>
                          {s.label}
                        </option>
                      ))}
                    </select>
                  </div>
                );
              })}
              {stageLeads.length === 0 && (
                <p className="py-4 text-center text-xs text-slate-400">No cases</p>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

/** @deprecated Use AdmissionsPipelineBoard — legacy kanban alias */
export const AdmissionsCasePipelineBoard = AdmissionsPipelineBoard;

"use client";

import { useTransition } from "react";
import {
  cancelQueuedCommunication,
  customizeQueuedCommunication,
  resendCommunication,
  sendManualCommunication,
} from "@/lib/admissions/communications/actions";
import type { ApplicantTimelineEntry } from "@/lib/admissions/communications/queries";
import type {
  CommunicationRecord,
  QueuedCommunication,
} from "@/lib/admissions/communications/types";
import { CHANNEL_LABELS } from "@/lib/admissions/communications/types";

interface CommunicationTimelineProps {
  leadId: string;
  applicationId?: string | null;
  guardianEmail: string | null;
  timeline: ApplicantTimelineEntry[];
  communications: CommunicationRecord[];
  pendingQueue: QueuedCommunication[];
}

function channelBadge(channel?: string) {
  const colors: Record<string, string> = {
    email: "bg-blue-100 text-blue-700",
    sms: "bg-emerald-100 text-emerald-700",
    portal_notification: "bg-violet-100 text-violet-700",
    internal_note: "bg-amber-100 text-amber-700",
  };
  const label = channel ? (CHANNEL_LABELS[channel as keyof typeof CHANNEL_LABELS] ?? channel) : "Event";
  return (
    <span className={`rounded-full px-2 py-0.5 text-xs font-medium ${colors[channel ?? ""] ?? "bg-slate-100 text-slate-600"}`}>
      {label}
    </span>
  );
}

function typeIcon(type: ApplicantTimelineEntry["type"]) {
  if (type === "communication") return "✉";
  if (type === "note") return "📝";
  if (type === "decision") return "⚖";
  return "→";
}

export function CommunicationTimeline({
  leadId,
  applicationId,
  guardianEmail,
  timeline,
  communications,
  pendingQueue,
}: CommunicationTimelineProps) {
  const [isPending, startTransition] = useTransition();

  return (
    <div className="space-y-6">
      <div className="rounded-2xl border border-slate-200/80 bg-white p-6">
        <div className="flex items-center justify-between gap-4">
          <div>
            <h3 className="text-sm font-semibold text-slate-900">Applicant Timeline</h3>
            <p className="mt-1 text-xs text-slate-500">
              All emails, SMS, portal notifications, notes, and stage changes
            </p>
          </div>
        </div>

        <div className="mt-6 space-y-4">
          {timeline.length === 0 && (
            <p className="text-sm text-slate-500">No activity recorded yet.</p>
          )}
          {timeline.map((entry) => (
            <div key={`${entry.type}-${entry.id}`} className="flex gap-3 border-l-2 border-slate-100 pl-4">
              <span className="text-sm" aria-hidden>{typeIcon(entry.type)}</span>
              <div className="min-w-0 flex-1">
                <div className="flex flex-wrap items-center gap-2">
                  <p className="text-sm font-medium text-slate-900">{entry.title}</p>
                  {entry.channel && channelBadge(entry.channel)}
                  {entry.deliveryStatus && (
                    <span className="text-xs text-slate-400">{entry.deliveryStatus}</span>
                  )}
                  {entry.openStatus && entry.openStatus !== "unknown" && (
                    <span className="text-xs text-slate-400">· {entry.openStatus}</span>
                  )}
                </div>
                {entry.body && (
                  <p className="mt-1 whitespace-pre-wrap text-sm text-slate-600 line-clamp-4">{entry.body}</p>
                )}
                <p className="mt-1 text-xs text-slate-400">
                  {new Date(entry.timestamp).toLocaleString()}
                  {entry.sentBy ? ` · ${entry.sentBy}` : ""}
                  {entry.templateKey ? ` · ${entry.templateKey}` : ""}
                </p>
                {entry.type === "communication" && entry.channel === "email" && (
                  <form
                    className="mt-2"
                    action={(fd) => {
                      startTransition(async () => {
                        fd.set("communication_id", entry.id);
                        fd.set("lead_id", leadId);
                        await resendCommunication(fd);
                      });
                    }}
                  >
                    <button
                      type="submit"
                      disabled={isPending}
                      className="text-xs font-medium text-brand-600 hover:text-brand-700"
                    >
                      Resend
                    </button>
                  </form>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>

      {pendingQueue.length > 0 && (
        <div className="rounded-2xl border border-amber-200/80 bg-amber-50/50 p-6">
          <h3 className="text-sm font-semibold text-slate-900">Scheduled Communications</h3>
          <div className="mt-4 space-y-3">
            {pendingQueue.map((item) => (
              <div key={item.id} className="rounded-xl border border-amber-100 bg-white p-4">
                <div className="flex flex-wrap items-center justify-between gap-2">
                  <div>
                    <p className="text-sm font-medium text-slate-900">{item.template_key}</p>
                    <p className="text-xs text-slate-500">
                      {channelBadge(item.channel)} · {new Date(item.scheduled_for).toLocaleString()}
                    </p>
                  </div>
                  <button
                    type="button"
                    disabled={isPending}
                    onClick={() =>
                      startTransition(async () => {
                        await cancelQueuedCommunication(item.id, leadId);
                      })
                    }
                    className="text-xs font-medium text-red-600 hover:text-red-700"
                  >
                    Cancel
                  </button>
                </div>
                <form
                  className="mt-3 space-y-2"
                  action={(fd) => {
                    startTransition(async () => {
                      fd.set("queue_id", item.id);
                      fd.set("lead_id", leadId);
                      await customizeQueuedCommunication(fd);
                    });
                  }}
                >
                  <input type="hidden" name="queue_id" value={item.id} />
                  <input type="hidden" name="lead_id" value={leadId} />
                  <input
                    name="subject"
                    placeholder="Custom subject (optional)"
                    defaultValue={item.custom_subject ?? ""}
                    className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm"
                  />
                  <textarea
                    name="body"
                    placeholder="Custom body (optional)"
                    defaultValue={item.custom_body ?? ""}
                    rows={2}
                    className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm"
                  />
                  <button
                    type="submit"
                    disabled={isPending}
                    className="rounded-lg bg-brand-600 px-3 py-1.5 text-xs font-medium text-white hover:bg-brand-700"
                  >
                    Save customization
                  </button>
                </form>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="rounded-2xl border border-slate-200/80 bg-white p-6">
        <h3 className="text-sm font-semibold text-slate-900">Send Manual Communication</h3>
        <form
          className="mt-4 space-y-3"
          action={(fd) => {
            startTransition(async () => {
              await sendManualCommunication(fd);
            });
          }}
        >
          <input type="hidden" name="lead_id" value={leadId} />
          {applicationId && <input type="hidden" name="application_id" value={applicationId} />}
          <div className="grid gap-3 sm:grid-cols-2">
            <select name="channel" className="rounded-lg border border-slate-200 px-3 py-2 text-sm">
              <option value="email">Email</option>
              <option value="sms">SMS</option>
              <option value="portal_notification">Portal Notification</option>
              <option value="internal_note">Internal Note</option>
            </select>
            <input
              name="sent_to"
              defaultValue={guardianEmail ?? ""}
              placeholder="Recipient"
              className="rounded-lg border border-slate-200 px-3 py-2 text-sm"
            />
          </div>
          <input
            name="subject"
            placeholder="Subject"
            required
            className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm"
          />
          <textarea
            name="body"
            placeholder="Message body — use {{student_name}}, {{parent_name}}, {{portal_link}}, etc."
            required
            rows={4}
            className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm"
          />
          <button
            type="submit"
            disabled={isPending}
            className="rounded-xl bg-brand-600 px-4 py-2 text-sm font-medium text-white hover:bg-brand-700"
          >
            Send now
          </button>
        </form>
      </div>
    </div>
  );
}

