}

function safeDiv(numerator: number, denominator: number): number {
  return denominator !== 0 ? numerator / denominator : 0;
}

function pct(numerator: number, denominator: number): number {
  return safeDiv(numerator, denominator) * 100;
}

function riskLevel(
  value: number,
  thresholds: { critical: number; high: number; medium: number }
): FinanceRiskLevel {
  if (value >= thresholds.critical) return "critical";
  if (value >= thresholds.high) return "high";
  if (value >= thresholds.medium) return "medium";
  return "low";
}

export class FinanceExecutiveIntelligence {
  private readonly now: () => Date;

  constructor(deps?: FinanceExecutiveIntelligenceDependencies) {
    this.now = deps?.now ?? (() => new Date());
  }

  /** Calculate the full suite of executive KPIs from a financial snapshot. */
  calculateKPIs(snapshot: FinancialSnapshot): FinanceExecutiveKPIs {
    // ---------------------------------------------------------------------------
    // Profitability
    // ---------------------------------------------------------------------------
    const ebitda = snapshot.ebitda;
    const operatingMargin = pct(
      snapshot.totalRevenue - snapshot.totalExpenses,
      snapshot.totalRevenue
    );

    // ---------------------------------------------------------------------------
    // Liquidity
    // ---------------------------------------------------------------------------
    const dailyBurn =
      snapshot.monthlyBurnRate > 0 ? snapshot.monthlyBurnRate / 30 : 1;
    const cashRunwayDays = Math.floor(snapshot.cash / dailyBurn);
    const dailyExpenses = snapshot.totalExpenses / 365;
    const daysCashOnHand = Math.floor(safeDiv(snapshot.cash, dailyExpenses));
    const currentRatio = safeDiv(snapshot.currentAssets, snapshot.currentLiabilities);
    const quickRatio = safeDiv(
      snapshot.currentAssets - snapshot.inventory,
      snapshot.currentLiabilities
    );

    // ---------------------------------------------------------------------------
    // Growth
    // ---------------------------------------------------------------------------
    const revenueGrowth = pct(
      snapshot.totalRevenue - snapshot.priorPeriodRevenue,
      snapshot.priorPeriodRevenue
    );
    const expenseGrowth = pct(
      snapshot.totalExpenses - snapshot.priorPeriodExpenses,
      snapshot.priorPeriodExpenses
    );

    // ---------------------------------------------------------------------------
    // Revenue composition
    // ---------------------------------------------------------------------------
    const enrollmentRevenue = snapshot.tuitionRevenue;
    const grantDependency = pct(snapshot.grantRevenue, snapshot.totalRevenue);

    // ---------------------------------------------------------------------------
    // Expense ratios
    // ---------------------------------------------------------------------------
    const payrollPercent = pct(snapshot.payrollExpense, snapshot.totalExpenses);
    const instructionPercent = pct(
      snapshot.instructionExpense,
      snapshot.totalExpenses
    );
    const administrativePercent = pct(
      snapshot.administrativeExpense,
      snapshot.totalExpenses
    );
    const facilityPercent = pct(
      snapshot.facilityExpense,
      snapshot.totalExpenses
    );
    const fundraisingPercent = pct(
      snapshot.fundraisingExpense,
      snapshot.totalExpenses
    );

    // ---------------------------------------------------------------------------
    // Budget variance (revenue: positive = above budget)
    // ---------------------------------------------------------------------------
    const budgetVariance = pct(
      snapshot.totalRevenue - snapshot.budgetedRevenue,
      snapshot.budgetedRevenue
    );

    // Forecast accuracy (100% = perfect; lower = less accurate)
    const forecastAccuracy = Math.max(
      0,
      100 - Math.abs(budgetVariance)
    );

    // ---------------------------------------------------------------------------
    // Risk assessments
    // ---------------------------------------------------------------------------
    const liquidityRisk: FinanceRiskLevel = (() => {
      if (cashRunwayDays < 30 || currentRatio < 0.5) return "critical";
      if (cashRunwayDays < 60 || currentRatio < 1.0) return "high";
      if (cashRunwayDays < 90 || currentRatio < 1.5) return "medium";
      return "low";
    })();

    const collectionsRisk: FinanceRiskLevel = (() => {
      const overduePct = pct(snapshot.overdueReceivables, snapshot.totalReceivables);
      if (overduePct >= 40) return "critical";
      if (overduePct >= 25) return "high";
      if (overduePct >= 10) return "medium";
      return "low";
    })();

    const vendorRisk: FinanceRiskLevel = (() => {
      if (snapshot.criticalVendorCount === 0) return "low";
      const ratio = snapshot.criticalVendorCount / Math.max(snapshot.activeVendorCount, 1);
      if (ratio >= 0.3) return "critical";
      if (ratio >= 0.2) return "high";
      if (ratio >= 0.1) return "medium";
      return "low";
    })();

    const grantRisk: FinanceRiskLevel = (() => {
      if (grantDependency >= 80) return "critical";
      if (grantDependency >= 60) return "high";
      if (grantDependency >= 40) return "medium";
      return "low";
    })();

    return {
      asOfDate: snapshot.asOfDate,
      currency: snapshot.currency,
      ebitda,
      operatingMargin,
      cashRunwayDays,
      daysCashOnHand,
      currentRatio,
      quickRatio,
      revenueGrowth,
      expenseGrowth,
      enrollmentRevenue,
      grantDependency,
      payrollPercent,
      instructionPercent,
      administrativePercent,
      facilityPercent,
      fundraisingPercent,
      budgetVariance,
      forecastAccuracy,
      liquidityRisk,
      collectionsRisk,
      vendorRisk,
      grantRisk,
    };
  }

  /** Quick liquidity check. */
  isLiquiditySufficient(snapshot: FinancialSnapshot, minRunwayDays = 60): boolean {
    const kpis = this.calculateKPIs(snapshot);
    return kpis.cashRunwayDays >= minRunwayDays;
  }

  /** Summarize top risks as a sorted list. */
  getRiskSummary(
    snapshot: FinancialSnapshot
  ): Array<{ area: string; level: FinanceRiskLevel }> {
    const kpis = this.calculateKPIs(snapshot);
    return [
      { area: "Liquidity", level: kpis.liquidityRisk },
      { area: "Collections", level: kpis.collectionsRisk },
      { area: "Vendor Concentration", level: kpis.vendorRisk },
      { area: "Grant Dependency", level: kpis.grantRisk },
    ].sort((a, b) => {
      const order: Record<FinanceRiskLevel, number> = {
        critical: 0,
        high: 1,
        medium: 2,
        low: 3,
      };
      return order[a.level] - order[b.level];
    });
  }
}

export function createFinanceExecutiveIntelligence(
  deps?: FinanceExecutiveIntelligenceDependencies
): FinanceExecutiveIntelligence {
  return new FinanceExecutiveIntelligence(deps);
}

/**
 * Enterprise Financial Intelligence Engine — Grants.
 *
 * Restricted/unrestricted grants, drawdowns, utilization tracking.
 */

import { createFinanceId } from "@/lib/platform/finance/ids";
import type {
  FinanceDimensionalContext,
  FinanceGrant,
  FinanceGrantDrawdown,
  FinanceGrantDrawdownStatus,
  FinanceGrantRestrictionType,
  FinanceGrantStatus,
  FinanceMetadata,
} from "@/lib/platform/finance/types";
import { emptyDimensions } from "@/lib/platform/finance/types";

export interface AddGrantInput {
  name: string;
  grantorName: string;
  restriction: FinanceGrantRestrictionType;
  totalAmount: number;
  periodStart: string;
  periodEnd: string;
  reimbursementBasis?: boolean;
  currency?: string;
  dimensions?: FinanceDimensionalContext;
  metadata?: FinanceMetadata;
}

export interface RecordDrawdownInput {
  grantId: string;
  requestedAmount: number;
  memo: string;
  currency?: string;
  dimensions?: FinanceDimensionalContext;
  metadata?: FinanceMetadata;
}

export interface GrantUtilization {
  grantId: string;
  totalAmount: number;
  utilizedAmount: number;
  remainingAmount: number;
  percent: number;
}

export interface FinanceGrantsDependencies {
  createId?: (prefix: string) => string;
  now?: () => Date;
}

export class FinanceGrants {
  private readonly grants = new Map<string, FinanceGrant>();
  private readonly drawdowns = new Map<string, FinanceGrantDrawdown>();
  private readonly createId: (prefix: string) => string;
  private readonly now: () => Date;
  private drawdownSequence = 0;

  constructor(deps?: FinanceGrantsDependencies) {
    this.createId = deps?.createId ?? ((prefix) => createFinanceId(prefix));
    this.now = deps?.now ?? (() => new Date());
  }

  addGrant(input: AddGrantInput): FinanceGrant {
    const id = this.createId("grant");
    const grant: FinanceGrant = {
      id,
      name: input.name,
      grantorName: input.grantorName,
      restriction: input.restriction,
      totalAmount: input.totalAmount,
      utilizedAmount: 0,
      remainingAmount: input.totalAmount,
      periodStart: input.periodStart,
      periodEnd: input.periodEnd,
      status: "active",
      reimbursementBasis: input.reimbursementBasis ?? false,
      dimensions: input.dimensions ?? emptyDimensions(),
      createdAt: this.now().toISOString(),
      metadata: input.metadata,
    };
    this.grants.set(id, grant);
    return grant;
  }

  getGrant(id: string): FinanceGrant | undefined {
    return this.grants.get(id);
  }

  listGrants(): FinanceGrant[] {
    return [...this.grants.values()].sort((a, b) =>
      a.periodStart.localeCompare(b.periodStart)
    );
  }

  listByStatus(status: FinanceGrantStatus): FinanceGrant[] {
    return this.listGrants().filter((g) => g.status === status);
  }

  updateGrantStatus(grantId: string, status: FinanceGrantStatus): FinanceGrant {
    const grant = this.getGrantOrThrow(grantId);
    const updated: FinanceGrant = { ...grant, status };
    this.grants.set(grantId, updated);
    return updated;
  }

  /** Record a drawdown request against a grant. */
  recordDrawdown(input: RecordDrawdownInput): FinanceGrantDrawdown {
    this.drawdownSequence += 1;
    const grant = this.getGrantOrThrow(input.grantId);
    const id = this.createId("dd");
    const currency = input.currency ?? "USD";

    const drawdown: FinanceGrantDrawdown = {
      id,
      grantId: input.grantId,
      drawdownNumber: `DD-${String(this.drawdownSequence).padStart(5, "0")}`,
      timestamp: this.now().toISOString(),
      dimensions: input.dimensions ?? grant.dimensions,
      amount: { amount: input.requestedAmount, currency },
      memo: input.memo,
      reversedById: null,
      reversesId: null,
      requestedAmount: input.requestedAmount,
      approvedAmount: null,
      currency,
      status: "submitted",
      metadata: input.metadata,
    };
    this.drawdowns.set(id, drawdown);
    return drawdown;
  }

  /** Approve a drawdown and update grant utilization. */
  approveDrawdown(
    drawdownId: string,
    approvedAmount?: number
  ): FinanceGrantDrawdown {
    const dd = this.getDrawdownOrThrow(drawdownId);
    const approved = approvedAmount ?? dd.requestedAmount;
    const updatedDd: FinanceGrantDrawdown = {
      ...dd,
      status: "approved",
      approvedAmount: approved,
    };
    this.drawdowns.set(drawdownId, updatedDd);

    // Update grant utilization
    const grant = this.getGrantOrThrow(dd.grantId);
    const newUtilized = Math.min(
      grant.utilizedAmount + approved,
      grant.totalAmount
    );
    const updated: FinanceGrant = {
      ...grant,
      utilizedAmount: newUtilized,
      remainingAmount: grant.totalAmount - newUtilized,
    };
    this.grants.set(dd.grantId, updated);
    return updatedDd;
  }

  getDrawdown(id: string): FinanceGrantDrawdown | undefined {
    return this.drawdowns.get(id);
  }

  listDrawdowns(grantId?: string): FinanceGrantDrawdown[] {
    const all = [...this.drawdowns.values()].sort((a, b) =>
      a.timestamp.localeCompare(b.timestamp)
    );
    return grantId ? all.filter((d) => d.grantId === grantId) : all;
  }

  getUtilization(grantId: string): GrantUtilization {
    const grant = this.getGrantOrThrow(grantId);
    const percent =
      grant.totalAmount > 0
        ? (grant.utilizedAmount / grant.totalAmount) * 100
        : 0;
    return {
      grantId,
      totalAmount: grant.totalAmount,
      utilizedAmount: grant.utilizedAmount,
      remainingAmount: grant.remainingAmount,
      percent,
    };
  }

  /** Total remaining across all active grants. */
  getTotalAvailableFunding(): number {
    return this.listByStatus("active").reduce(
      (s, g) => s + g.remainingAmount,
      0
    );
  }

  private getGrantOrThrow(id: string): FinanceGrant {
    const g = this.grants.get(id);
    if (!g) throw new Error(`Grant not found: ${id}`);
    return g;
  }

  private getDrawdownOrThrow(id: string): FinanceGrantDrawdown {
    const d = this.drawdowns.get(id);
    if (!d) throw new Error(`Drawdown not found: ${id}`);
    return d;
  }
}

export function createFinanceGrants(
  deps?: FinanceGrantsDependencies
): FinanceGrants {
  return new FinanceGrants(deps);
}

/**
 * Enterprise Financial Intelligence Engine — Payments.
 *
 * ACH, check, wire, card, Square (port abstraction), allocation, refunds.
 * Immutable: payments are reversed, not deleted.
 */

import { createFinanceId } from "@/lib/platform/finance/ids";
import type { FinanceAccountsReceivable } from "@/lib/platform/finance/ar";
import type { FinanceGeneralLedger } from "@/lib/platform/finance/ledger";
import type {
  FinanceDimensionalContext,
  FinanceMetadata,
  FinancePayment,
  FinancePaymentAllocation,
  FinancePaymentDirection,
  FinancePaymentMethod,
  FinancePaymentStatus,
} from "@/lib/platform/finance/types";

// ---------------------------------------------------------------------------
// Square port abstraction
// ---------------------------------------------------------------------------

export interface SquarePort {
  processPayment(
    amount: number,
    currency: string,
    metadata: Record<string, unknown>
  ): Promise<{ id: string; status: string }>;
}

export class InMemorySquarePort implements SquarePort {
  async processPayment(
    _amount: number,
    _currency: string,
    _metadata: Record<string, unknown>
  ): Promise<{ id: string; status: string }> {
    return { id: `sq-${Date.now()}`, status: "completed" };
  }
}

// ---------------------------------------------------------------------------
// Payments service
// ---------------------------------------------------------------------------

export interface RecordPaymentInput {
  method: FinancePaymentMethod;
  direction: FinancePaymentDirection;
  amount: number;
  currency?: string;
  memo: string;
  bankAccountId?: string | null;
  referenceNumber?: string | null;
  dimensions: FinanceDimensionalContext;
  allocations?: FinancePaymentAllocation[];
  metadata?: FinanceMetadata;
}

export interface FinancePaymentsDependencies {
  gl?: FinanceGeneralLedger;
  ar?: FinanceAccountsReceivable;
  squarePort?: SquarePort;
  cashAccountCode?: string;
  arAccountCode?: string;
  createId?: (prefix: string) => string;
  now?: () => Date;
}

export class FinancePayments {
  private readonly payments = new Map<string, FinancePayment>();
  private readonly gl: FinanceGeneralLedger | null;
  private readonly ar: FinanceAccountsReceivable | null;
  private readonly squarePort: SquarePort;
  private readonly cashAccountCode: string;
  private readonly arAccountCode: string;
  private readonly createId: (prefix: string) => string;
  private readonly now: () => Date;
  private paymentSequence = 0;

  constructor(deps?: FinancePaymentsDependencies) {
    this.gl = deps?.gl ?? null;
    this.ar = deps?.ar ?? null;
    this.squarePort = deps?.squarePort ?? new InMemorySquarePort();
    this.cashAccountCode = deps?.cashAccountCode ?? "1000";
    this.arAccountCode = deps?.arAccountCode ?? "1100";
    this.createId = deps?.createId ?? ((prefix) => createFinanceId(prefix));
    this.now = deps?.now ?? (() => new Date());
  }

  recordPayment(input: RecordPaymentInput): FinancePayment {
    this.paymentSequence += 1;
    const id = this.createId("pmt");
    const paymentNumber = `PMT-${String(this.paymentSequence).padStart(6, "0")}`;
    const currency = input.currency ?? "USD";

    const payment: FinancePayment = {
      id,
      paymentNumber,
      timestamp: this.now().toISOString(),
      dimensions: input.dimensions,
      amount: { amount: input.amount, currency },
      memo: input.memo,
      reversedById: null,
      reversesId: null,
      method: input.method,
      direction: input.direction,
      status: "completed",
      bankAccountId: input.bankAccountId ?? null,
      referenceNumber: input.referenceNumber ?? null,
      allocations: input.allocations ?? [],
      currency,
      refundedAmount: 0,
      metadata: input.metadata,
    };
    this.payments.set(id, payment);

    // Apply allocations to AR invoices if AR injected
    if (this.ar && input.allocations) {
      for (const alloc of input.allocations) {
        if (alloc.invoiceId) {
          this.ar.recordPayment(alloc.invoiceId, alloc.allocatedAmount, id);
        }
      }
    }

    // Post cash/AR journal if GL injected and it's an inbound payment
    if (this.gl && input.direction === "inbound") {
      const coa = this.gl.chartOfAccounts;
      const cashAccount = coa.findByCode(this.cashAccountCode);
      const arAccount = coa.findByCode(this.arAccountCode);
      if (cashAccount && arAccount) {
        this.gl.postJournal({
          memo: `Payment ${paymentNumber} — ${input.memo}`,
          currency,
          dimensions: input.dimensions,
          postings: [
            { accountId: cashAccount.id, debit: input.amount, credit: 0 },
            { accountId: arAccount.id, debit: 0, credit: input.amount },
          ],
        });
      }
    }

    return payment;
  }

  /**
   * Refund a payment (partial or full).
   * Immutable — creates a new outbound payment linked to the original.
   */
  refund(
    paymentId: string,
    amount: number,
    memo: string,
    dimensions: FinanceDimensionalContext
  ): FinancePayment {
    const original = this.payments.get(paymentId);
    if (!original) throw new Error(`Payment not found: ${paymentId}`);
    if (original.status === "refunded" || original.status === "voided") {
      throw new Error(`Payment ${paymentId} cannot be refunded`);
    }

    this.paymentSequence += 1;
    const refundId = this.createId("pmt");
    const refundPaymentNumber = `PMT-${String(this.paymentSequence).padStart(6, "0")}-REF`;

    const refund: FinancePayment = {
      id: refundId,
      paymentNumber: refundPaymentNumber,
      timestamp: this.now().toISOString(),
      dimensions,
      amount: { amount: amount, currency: original.currency },
      memo,
      reversedById: null,
      reversesId: paymentId,
      method: original.method,
      direction: "outbound",
      status: "completed",
      bankAccountId: original.bankAccountId,
      referenceNumber: null,
      allocations: [],
      currency: original.currency,
      refundedAmount: 0,
    };
    this.payments.set(refundId, refund);

    // Mark original as having refunded amount
    const updatedOriginal: FinancePayment = {
      ...original,
      refundedAmount: original.refundedAmount + amount,
      status:
        original.refundedAmount + amount >= original.amount.amount
          ? "refunded"
          : original.status,
      reversedById: refundId,
    };
    this.payments.set(paymentId, updatedOriginal);

    return refund;
  }

  getPayment(id: string): FinancePayment | undefined {
    return this.payments.get(id);
  }

  listPayments(): FinancePayment[] {
    return [...this.payments.values()].sort((a, b) =>
      a.timestamp.localeCompare(b.timestamp)
    );
  }

  listByDirection(direction: FinancePaymentDirection): FinancePayment[] {
    return this.listPayments().filter((p) => p.direction === direction);
  }

  listByStatus(status: FinancePaymentStatus): FinancePayment[] {
    return this.listPayments().filter((p) => p.status === status);
  }

  /** Process a Square payment (async via port). */
  async processSquarePayment(
    input: RecordPaymentInput & { currency: string }
  ): Promise<FinancePayment> {
    const squareResult = await this.squarePort.processPayment(
      input.amount,
      input.currency,
      { memo: input.memo }
    );
    return this.recordPayment({
      ...input,
      method: "square",
      referenceNumber: squareResult.id,
      metadata: { ...input.metadata, squareId: squareResult.id },
    });
  }
}

export function createFinancePayments(
  deps?: FinancePaymentsDependencies
): FinancePayments {
  return new FinancePayments(deps);
}

/**
 * Enterprise Governance & Accountability — cycle orchestrator (Sprint 017).
 */

import { GovernanceAccountability } from "@/lib/platform/governance/accountability";
import { GovernanceApprovals } from "@/lib/platform/governance/approvals";
import { GovernanceAudit } from "@/lib/platform/governance/audit";
import { GovernanceAuthority } from "@/lib/platform/governance/authority";
import { GovernanceBoard } from "@/lib/platform/governance/board";
import { GovernanceCommittees } from "@/lib/platform/governance/committees";
import { GovernanceCompliance } from "@/lib/platform/governance/compliance";
import { GovernanceDelegations } from "@/lib/platform/governance/delegations";
import { GovernanceEvidence } from "@/lib/platform/governance/evidence";
import { GovernanceHistory } from "@/lib/platform/governance/history";
import { GovernanceMetrics } from "@/lib/platform/governance/metrics";
import { GovernanceNotifications } from "@/lib/platform/governance/notifications";
import { GovernanceOversight } from "@/lib/platform/governance/oversight";
import { GovernancePolicies } from "@/lib/platform/governance/policies";
import { GovernanceReports } from "@/lib/platform/governance/reports";
import { GovernanceScorecards } from "@/lib/platform/governance/scorecards";
import { GovernanceVoting } from "@/lib/platform/governance/voting";
import {
  ENTERPRISE_GOVERNANCE_VERSION,
  type GovernanceCycleRequest,
  type GovernanceCycleResult,
} from "@/lib/platform/governance/types";

export interface EnterpriseGovernanceEngineDependencies {
  policies?: GovernancePolicies;
  approvals?: GovernanceApprovals;
  delegations?: GovernanceDelegations;
  board?: GovernanceBoard;
  committees?: GovernanceCommittees;
  voting?: GovernanceVoting;
  accountability?: GovernanceAccountability;
  audit?: GovernanceAudit;
  evidence?: GovernanceEvidence;
  compliance?: GovernanceCompliance;
  authority?: GovernanceAuthority;
  oversight?: GovernanceOversight;
  reports?: GovernanceReports;
  scorecards?: GovernanceScorecards;
  metrics?: GovernanceMetrics;
  history?: GovernanceHistory;
  notifications?: GovernanceNotifications;
  now?: () => Date;
  createId?: (prefix: string) => string;
}

/**
 * Fully wired Enterprise Governance engine.
 */
export class EnterpriseGovernanceEngine {
  readonly policies: GovernancePolicies;
  readonly approvals: GovernanceApprovals;
  readonly delegations: GovernanceDelegations;
  readonly board: GovernanceBoard;
  readonly committees: GovernanceCommittees;
  readonly voting: GovernanceVoting;
  readonly accountability: GovernanceAccountability;
  readonly audit: GovernanceAudit;
  readonly evidence: GovernanceEvidence;
  readonly compliance: GovernanceCompliance;
  readonly authority: GovernanceAuthority;
  readonly oversight: GovernanceOversight;
  readonly reports: GovernanceReports;
  readonly scorecards: GovernanceScorecards;
  readonly metrics: GovernanceMetrics;
  readonly history: GovernanceHistory;
  readonly notifications: GovernanceNotifications;
  private readonly now: () => Date;

  constructor(dependencies: EnterpriseGovernanceEngineDependencies = {}) {
    const now = dependencies.now ?? (() => new Date());
    const createId = dependencies.createId;
    this.now = now;

    this.policies =
      dependencies.policies ?? new GovernancePolicies({ now, createId });
    this.approvals =
      dependencies.approvals ?? new GovernanceApprovals({ now, createId });
    this.delegations =
      dependencies.delegations ?? new GovernanceDelegations({ now, createId });
    this.board = dependencies.board ?? new GovernanceBoard({ now, createId });
    this.committees =
      dependencies.committees ?? new GovernanceCommittees({ createId });
    this.voting = dependencies.voting ?? new GovernanceVoting({ now, createId });
    this.accountability =
      dependencies.accountability ??
      new GovernanceAccountability({ now, createId });
    this.audit = dependencies.audit ?? new GovernanceAudit({ now, createId });
    this.evidence =
      dependencies.evidence ?? new GovernanceEvidence({ now, createId });
    this.compliance =
      dependencies.compliance ?? new GovernanceCompliance({ now, createId });
    this.authority =
      dependencies.authority ?? new GovernanceAuthority({ createId });
    this.oversight =
      dependencies.oversight ?? new GovernanceOversight({ now, createId });
    this.reports =
      dependencies.reports ?? new GovernanceReports({ now, createId });
    this.scorecards =
      dependencies.scorecards ?? new GovernanceScorecards({ now, createId });
    this.metrics = dependencies.metrics ?? new GovernanceMetrics({ now });
    this.history =
      dependencies.history ?? new GovernanceHistory({ createId });
    this.notifications =
      dependencies.notifications ??
      new GovernanceNotifications({ now, createId });
  }

  /**
   * Run one enterprise governance accountability cycle.
   */
  run(request: GovernanceCycleRequest): GovernanceCycleResult {
    const policies = this.policies.list();
    const approvals = this.approvals.createFromCycle(request);
    const boardPack = this.board.syncFromCycle(request);
    const committees = this.committees.list();
    const evidence = this.evidence.syncFromCycle(request);
    const accountability = this.accountability.syncFromCycle(request, approvals);
    const compliance = this.compliance.evaluate(request, policies);

    const votes = boardPack.motions.map((motion) => {
      const vote = this.voting.open({
        subjectId: motion.motionId,
        subjectKind: "motion",
      });
      return vote;
    });

    const delegations = this.delegations.list();
    const authority = this.authority.list();

    const auditEvents = this.audit.recordCycle(request, {
      approvals,
      motions: boardPack.motions,
      resolutions: boardPack.resolutions,
      delegations,
    });

    for (const vote of votes) {
      this.audit.record({
        kind: "vote",
        title: `Vote opened for ${vote.subjectId}`,
        detail: `Subject kind ${vote.subjectKind}`,
        actor: request.actor ?? "governance-engine",
        relatedIds: [vote.voteId, vote.subjectId],
        organizationId: request.organizationId,
        schoolId: request.schoolId ?? null,
      });
    }

    const allAudit = this.audit.list();
    const oversight = [
      this.oversight.reviewCycle(request, {
        approvals,
        accountability,
        compliance,
      }),
    ];

    for (const review of oversight) {
      this.audit.record({
        kind: "oversight_review",
        title: review.title,
        detail: review.findings.join("; "),
        actor: review.reviewer,
        relatedIds: [review.reviewId],
        organizationId: request.organizationId,
        schoolId: request.schoolId ?? null,
      });
    }

    const notifications = this.notifications.notifyCycle(request, {
      approvals,
      compliance,
      oversight,
    });

    const history = this.history.fromAudit(this.audit.list());

    const metrics = this.metrics.collect({
      approvals,
      accountability,
      compliance,
      auditEvents: this.audit.list(),
      boardGoalCount: boardPack.goals.length,
      motionCount: boardPack.motions.length,
    });

    const scorecard = this.scorecards.generate(metrics);
    const openApprovals = approvals.filter((a) => a.status === "pending").length;
    const openAccountability = accountability.filter(
      (a) =>
        a.status === "open" ||
        a.status === "in_progress" ||
        a.status === "overdue"
    ).length;
    const openFindings = compliance.filter(
      (c) => c.status !== "compliant" && c.status !== "waived"
    ).length;

    const report = this.reports.build({
      subject: request.subject,
      scorecard,
      metrics,
      openApprovals,
      openAccountability,
      openFindings,
      auditEventCount: this.audit.list().length,
    });

    return {
      requestId: request.requestId,
      completedAt: this.now().toISOString(),
      policies,
      approvals,
      delegations,
      boardGoals: boardPack.goals,
      boardDecisions: boardPack.decisions,
      motions: boardPack.motions,
      resolutions: boardPack.resolutions,
      committees,
      votes,
      accountability,
      auditEvents: this.audit.list(),
      evidence,
      compliance,
      authority,
      oversight,
      notifications,
      history,
      metrics,
      scorecard,
      report,
      domainVersion: ENTERPRISE_GOVERNANCE_VERSION,
      summary: report.narrative,
      metadata: {
        recommendationAuditCount: allAudit.filter((e) => e.kind === "recommendation")
          .length,
        sourceAutonomyId: request.autonomy?.requestId ?? null,
        sourceDecisionId: request.decision?.requestId ?? null,
      },
    };
  }
}

