      totalAmt: 4800,
      balance: 0,
      dueDate: earlier,
    }, earlier),
    entity("bill", "bill-2003", orgId, companyId, 1, {
      name: "Bill 2003",
      vendorId: "vend-1",
      status: "OVERDUE",
      totalAmt: 3200,
      balance: 3200,
      dueDate: monthAgo,
    }, now),

    entity("payment", "pay-3001", orgId, companyId, 2, {
      name: "Payment 3001",
      customerId: "cust-1",
      totalAmt: 6500,
      txnDate: earlier,
    }, earlier),
    entity("payment", "pay-3002", orgId, companyId, 1, {
      name: "Payment 3002",
      customerId: "cust-2",
      totalAmt: 450,
      txnDate: now,
    }, now),

    entity("bill_payment", "bpay-3101", orgId, companyId, 1, {
      name: "Bill payment 3101",
      vendorId: "vend-2",
      totalAmt: 4800,
      txnDate: earlier,
    }, earlier),

    entity("journal_entry", "je-4001", orgId, companyId, 1, {
      name: "JE accrual payroll",
      totalAmt: 82000,
      txnDate: earlier,
    }, earlier),

    entity("expense", "exp-5001", orgId, companyId, 2, {
      name: "Utilities July",
      totalAmt: 6400,
      accountId: "acc-5000",
      txnDate: now,
    }, now),
    entity("expense", "exp-5002", orgId, companyId, 1, {
      name: "Software licenses",
      totalAmt: 2800,
      accountId: "acc-5000",
      txnDate: earlier,
    }, earlier),

    entity("deposit", "dep-6001", orgId, companyId, 1, {
      name: "Tuition deposit batch",
      totalAmt: 128000,
      txnDate: earlier,
    }, earlier),

    entity("transfer", "xfer-7001", orgId, companyId, 1, {
      name: "Sweep to reserves",
      totalAmt: 25000,
      txnDate: earlier,
    }, earlier),

    entity("credit_memo", "cm-8001", orgId, companyId, 1, {
      name: "Credit memo 8001",
      customerId: "cust-1",
      totalAmt: 250,
      txnDate: now,
    }, now),

    entity("budget", "bud-fy26", orgId, companyId, 2, {
      name: "FY26 Operating Budget",
      fiscalYear: 2026,
      revenueBudget: 4_800_000,
      expenseBudget: 4_450_000,
      actualRevenue: 4_120_000,
      actualExpense: 3_890_000,
    }, now),

    entity("class", "class-ops", orgId, companyId, 1, {
      name: "Operations",
      active: true,
    }, now),
    entity("class", "class-acad", orgId, companyId, 1, {
      name: "Academics",
      active: true,
    }, now),

    entity("location", "loc-main", orgId, companyId, 1, {
      name: "Main Campus",
      active: true,
    }, now),

    entity("attachment", "att-1", orgId, companyId, 1, {
      name: "Invoice 1002 PDF",
      relatedId: "inv-1002",
      contentType: "application/pdf",
    }, now),
  ];

  let selectedCompanyId = companyId;
  let environment: QuickBooksEnvironment = "sandbox";
  const PAGE_SIZE = 25;

  return {
    async authenticate(input) {
      if (!input.accessToken || input.accessToken === "invalid") {
        return { ok: false, error: "Invalid QuickBooks access token" };
      }
      environment = input.environment ?? "sandbox";
      selectedCompanyId = input.companyId ?? companyId;
      return {
        ok: true,
        session: {
          environment,
          accessToken: input.accessToken,
          refreshToken: `qb-refresh-${input.accessToken}`,
          expiresAt: new Date(Date.now() + 3_600_000).toISOString(),
          companyId: selectedCompanyId,
          companies,
        },
      };
    },

    async refreshToken(refreshToken) {
      if (!refreshToken || refreshToken === "invalid") {
        return { ok: false, error: "Invalid QuickBooks refresh token" };
      }
      return {
        ok: true,
        accessToken: `qb-access-refreshed-${Date.now()}`,
        refreshToken: `qb-refresh-rotated-${Date.now()}`,
        expiresAt: new Date(Date.now() + 3_600_000).toISOString(),
      };
    },

    async listCompanies(accessToken) {
      if (!accessToken) return [];
      return companies;
    },

    async health() {
      return {
        ok: true,
        latencyMs: 22,
        environment,
        rateLimitRemaining: 460,
      };
    },

    async list(organizationId, objectType, since, cursor) {
      const orgOk =
        organizationId === orgId ||
        organizationId === "exec-demo-org" ||
        organizationId === "org-quickbooks-demo";
      if (!orgOk) return { records: [], nextCursor: null };

      let rows = catalog.filter((row) => {
        if (row.objectType !== objectType) return false;
        if (row.companyId !== selectedCompanyId && row.companyId !== companyId) return false;
        if (since && row.updatedAt < since) return false;
        return true;
      });

      const offset = cursor ? Number(cursor) || 0 : 0;
      const page = rows.slice(offset, offset + PAGE_SIZE);
      const next = offset + PAGE_SIZE < rows.length ? String(offset + PAGE_SIZE) : null;
      return { records: page, nextCursor: next };
    },
  };
}

export function allQuickBooksObjectTypes(): QuickBooksObjectType[] {
  return [...QUICKBOOKS_OBJECT_TYPES];
}

import { getEntityActivity } from "@/lib/platform/activity/query";
import type {
  EdgeResolveOptions,
  GraphEdge,
  GraphNode,
  GraphProvider,
  GraphProviderContext,
  GraphSearchQuery,
} from "@/lib/platform/intelligence-graph/types";
import { buildGraphNodeId } from "@/lib/platform/intelligence-graph/utils";

/** Graph provider backed by the Activity Engine — links activity events to entities. */
export const activityGraphProvider: GraphProvider = {
  providerKey: "activity",

  async resolveNode(
    _ctx: GraphProviderContext,
    entityType: string,
    entityId: string
  ): Promise<GraphNode | null> {
    if (entityType !== "activity_event" || !entityId) return null;

    return {
      nodeId: buildGraphNodeId("activity_event", entityType, entityId),
      nodeType: "activity_event",
      entityType,
      entityId,
      organizationId: null,
      schoolId: null,
      metadata: { providerKey: "activity" },
    };
  },

  async resolveEdges(
    ctx: GraphProviderContext,
    node: GraphNode,
    _options?: EdgeResolveOptions
  ): Promise<GraphEdge[]> {
    if (node.nodeType === "entity") {
      const activities = await getEntityActivity(ctx.supabase, node.entityType, node.entityId, {
        limit: 50,
      });

      return activities.map((activity) => ({
        edgeType: "activity.linked_to",
        sourceNode: buildGraphNodeId("activity_event", "activity_event", activity.id),
        targetNode: node.nodeId,
        direction: "directed" as const,
        weight: 0.5,
        effectiveDate: activity.occurred_at,
        endDate: null,
        metadata: {
          providerKey: "activity",
          eventType: activity.event_type,
          activityId: activity.id,
          title: activity.title,
        },
      }));
    }

    if (node.nodeType === "activity_event") {
      const { data } = await ctx.supabase
        .from("platform_activity_events")
        .select("*")
        .eq("id", node.entityId)
        .maybeSingle();

      if (!data) return [];

      return [
        {
