  WisdomIntelligenceServiceImpl as WisdomIntelligenceService,
  WisdomIntelligenceServiceImpl as WisdomService,
  WisdomIntelligenceServiceImpl as WisdomServiceImpl,
};

/**
 * JAG Collaboration — default agent adapters.
 *
 * Wraps Executive / Strategic / Decision Intelligence (and lightweight
 * domain heuristics) as {@link JagCollaboratingAgent} participants.
 * Does not replace empty stubs under `jag/agents/` — injectable adapters only.
 */

import type {
  JagAgentRecommendation,
  JagAgentResponse,
  JagCollaboratingAgent,
  JagCollaborationAgentRole,
  JagCollaborationRequest,
} from "@/lib/platform/jag/collaboration/types";
import {
  createDecisionIntelligenceDomain,
  type DecisionResolver,
} from "@/lib/platform/intelligence/decision";
import {
  createExecutiveIntelligenceDomain,
  type ExecutiveResolver,
} from "@/lib/platform/intelligence/domains/executive";
import {
  createStrategicIntelligenceDomain,
  type StrategicResolver,
} from "@/lib/platform/intelligence/domains/strategic";
import type { IntelligenceConfidenceScore } from "@/lib/platform/intelligence/types";

export interface DefaultCollaborationAgentsDependencies {
  executiveResolver?: ExecutiveResolver;
  strategicResolver?: StrategicResolver;
  decisionResolver?: DecisionResolver;
  now?: () => Date;
}

function confidence(value: number): IntelligenceConfidenceScore {
  return {
    value: Math.max(0, Math.min(1, value)),
    level: value >= 0.75 ? "high" : value >= 0.45 ? "medium" : value > 0 ? "low" : "unknown",
    factors: [],
  };
}

function timedResponse(
  role: JagCollaborationAgentRole,
  name: string,
  summary: string,
  recommendations: JagAgentRecommendation[],
  concerns: string[],
  conf: IntelligenceConfidenceScore,
  startedMs: number,
  now: () => Date
): JagAgentResponse {
  return {
    responseId: `${role}:${startedMs}`,
    agentRole: role,
    agentName: name,
    summary,
    recommendations,
    concerns,
    confidence: conf,
    elapsedMs: Math.max(0, now().getTime() - startedMs),
  };
}

/**
 * Build the default collaborating agent set.
 */
export function createDefaultCollaborationAgents(
  dependencies: DefaultCollaborationAgentsDependencies = {}
): JagCollaboratingAgent[] {
  const now = dependencies.now ?? (() => new Date());
  const executive =
    dependencies.executiveResolver ?? createExecutiveIntelligenceDomain();
  const strategic =
    dependencies.strategicResolver ?? createStrategicIntelligenceDomain();
  const decision =
    dependencies.decisionResolver ?? createDecisionIntelligenceDomain();

  const executiveAgent: JagCollaboratingAgent = {
    role: "executive",
    name: "Executive Intelligence Agent",
    weight: 1.4,
    participate(request) {
      const startedMs = now().getTime();
      const result = executive.analyze({
        requestId: `${request.requestId}:executive`,
        subject: request.subject,
        description: request.description,
        metadata: {
          ...request.metadata,
          sharedContext: request.sharedContext,
        },
      });
      const rec = result.recommendations.recommendations[0];
      const recommendation: JagAgentRecommendation = {
        recommendationKey: rec?.actionKey ?? "executive-briefing",
        title: rec?.label ?? result.briefing.summary.slice(0, 80),
        summary: result.briefing.summary,
        actions: result.recommendations.recommendations.map((r) => r.instruction),
        risk: result.classification.severity === "critical" ? 0.85 : 0.55,
        urgency: result.classification.severity === "critical" ? 0.9 : 0.6,
        impact: 0.75,
        cost: 0.5,
        missionAlignment: 0.7,
        confidence: result.classification.confidence,
        evidenceRefs: request.evidenceRefs ?? [],
      };
      return timedResponse(
        "executive",
        executiveAgent.name,
        result.briefing.summary,
        [recommendation],
        result.analysis.findings.slice(1).map((f) => f.title),
        result.classification.confidence,
        startedMs,
        now
      );
    },
  };

  const strategicAgent: JagCollaboratingAgent = {
    role: "strategic",
    name: "Strategic Intelligence Agent",
    weight: 1.2,
    participate(request) {
      const startedMs = now().getTime();
      const result = strategic.analyze({
        requestId: `${request.requestId}:strategic`,
        subject: request.subject,
        description: request.description,
        organizationId: request.organizationId,
        schoolId: request.schoolId,
        metadata: {
          ...request.metadata,
          sharedContext: request.sharedContext,
        },
      });
      const top = result.recommendations[0];
      const recommendation: JagAgentRecommendation = {
        recommendationKey: top?.recommendationId ?? "strategic-goal",
        title: top?.recommendedActions[0] ?? result.goals[0]?.title ?? "Strategic action",
        summary: result.brief.executiveSummary,
        actions: top?.recommendedActions ?? result.goals.map((g) => g.title),
        risk: result.goals[0]?.priority === "critical" ? 0.8 : 0.5,
        urgency: top?.urgency === "immediate" ? 0.9 : 0.55,
        impact: result.impact.overallScore,
        cost: 0.55,
        missionAlignment: 0.85,
        confidence: top?.confidence ?? result.goals[0]?.confidence ?? confidence(0.6),
        evidenceRefs: request.evidenceRefs ?? [],
      };
      return timedResponse(
        "strategic",
        strategicAgent.name,
        result.brief.executiveSummary,
        [recommendation],
        result.brief.risks,
        recommendation.confidence,
        startedMs,
        now
      );
    },
  };

  const decisionAgent: JagCollaboratingAgent = {
    role: "decision",
    name: "Decision Intelligence Agent",
    weight: 1.3,
    participate(request) {
      const startedMs = now().getTime();
      const result = decision.analyze({
        requestId: `${request.requestId}:decision`,
        subject: request.subject,
        description: request.description,
        organizationId: request.organizationId,
        schoolId: request.schoolId,
        sharedContext: request.sharedContext,
        memories: request.memories ? [...request.memories] : undefined,
        evidenceRefs: request.evidenceRefs ? [...request.evidenceRefs] : undefined,
        metadata: request.metadata,
      });
      const top = result.alternatives.alternatives[0];
      const recommendation: JagAgentRecommendation = {
        recommendationKey:
          result.recommendation.recommendedAlternativeId || "decision-option",
        title: result.recommendation.recommendedOption,
        summary: result.brief.decisionSummary,
        actions: top?.benefits.slice(0, 3) ?? result.recommendation.rationale,
        risk: result.risks.primaryRisk?.likelihood ?? 0.5,
        urgency: result.analysis.priority === "critical" ? 0.9 : 0.6,
        impact: result.impact.overallScore,
        cost: top ? Math.min(1, top.cost.amount / 100000) : 0.5,
        missionAlignment: 0.75,
        confidence: result.recommendation.confidence,
        evidenceRefs: request.evidenceRefs ?? [],
      };
      return timedResponse(
        "decision",
        decisionAgent.name,
        result.brief.decisionSummary,
        [recommendation],
        result.risks.risks.map((r) => r.title),
        result.recommendation.confidence,
        startedMs,
        now
      );
    },
  };

  const operationsAgent: JagCollaboratingAgent = {
    role: "operations",
    name: "Operations Agent",
    weight: 1.0,
    participate(request) {
      const startedMs = now().getTime();
      const recommendation: JagAgentRecommendation = {
        recommendationKey: "stabilize-operations",
        title: "Stabilize operational throughput",
        summary: `Operational response to "${request.subject}" with process controls and owners.`,
        actions: [
          "Assign operational owner",
          "Instrument leading process indicators",
          "Run a two-week stabilization sprint",
        ],
        risk: 0.45,
        urgency: 0.55,
        impact: 0.65,
        cost: 0.4,
        missionAlignment: 0.6,
        confidence: confidence(0.58),
        evidenceRefs: request.evidenceRefs ?? [],
      };
      return timedResponse(
        "operations",
        operationsAgent.name,
        recommendation.summary,
        [recommendation],
        ["Operational capacity may constrain aggressive timelines"],
        recommendation.confidence,
        startedMs,
        now
      );
    },
  };

  return [executiveAgent, strategicAgent, decisionAgent, operationsAgent];
}

import { randomUUID } from "crypto";
import { writePlatformAudit } from "@/lib/platform/automation/audit";
import { createMissionControlItem } from "@/lib/platform/automation/mission-control";
import { publishEvent } from "@/lib/platform/events/publisher/publish";
import { getLoopTransition, OPERATIONAL_LOOP_WORKFLOW_KEY } from "@/lib/platform/operational-loop/registry";
import type {
  LoopSideEffectResult,
  LoopTransitionContext,
  LoopTransitionResult,
  OperationalLoopTransitionKey,
  TransitionSideEffect,
} from "@/lib/platform/operational-loop/types";
import { publishPajEvent } from "@/lib/platform/paj/integration/events";
import { getPajJourneyByStudent } from "@/lib/platform/paj/persistence/records";
import { evaluateRuleSet } from "@/lib/platform/rules/engine/execute";
import { syncStudentPlatformRelationships } from "@/lib/students/platform-sync";
import { recordEntityWorkflowStateChange } from "@/lib/platform/workflow/engine/execute";
import { getActiveWorkflowInstance } from "@/lib/platform/workflow/persistence/instances";
import type { createAuthClient } from "@/lib/supabase/server-auth";

type AuthClient = Awaited<ReturnType<typeof createAuthClient>>;

const SIDE_EFFECT_ORDER: TransitionSideEffect[] = [
  "publish_event",
  "workflow_state",
  "rules_engine",
  "jag_profile",
  "paj_journey",
  "platform_audit",
  "mission_control",
  "executive_intelligence",
];

async function runSideEffect(
  supabase: AuthClient,
  effect: TransitionSideEffect,
  ctx: LoopTransitionContext,
  def: ReturnType<typeof getLoopTransition>,
  attemptId: string,
  fromStage: string | null,
  instanceId?: string
): Promise<LoopSideEffectResult> {
  try {
    switch (effect) {
      case "publish_event": {
        await publishEvent(
          {
            eventType: def.eventType,
            entityType: "student",
            entityId: ctx.studentId,
            organizationId: ctx.organizationId ?? undefined,
            schoolId: ctx.schoolId,
            actorId: ctx.actorUserId ?? undefined,
            payload: {
              transitionKey: ctx.transitionKey,
              fromStage: def.fromStage,
              toStage: def.toStage,
              attemptId,
              relatedEntityType: ctx.relatedEntityType,
              relatedEntityId: ctx.relatedEntityId,
              cycleNumber: ctx.cycleNumber ?? 1,
              ...ctx.facts,
            },
            metadata: ctx.metadata,
          },
          { persist: { supabase }, recordAudit: true }
        );
        return { effect, success: true, detail: def.eventType };
      }

      case "workflow_state": {
        const result = await recordEntityWorkflowStateChange(supabase, {
          workflowKey: OPERATIONAL_LOOP_WORKFLOW_KEY,
          domain: "sis",
          entityType: "student",
          entityId: ctx.studentId,
          schoolId: ctx.schoolId,
          organizationId: ctx.organizationId,
          fromStateKey: fromStage,
          toStateKey: def.toStage,
          transitionKey: ctx.transitionKey,
          actorUserId: ctx.actorUserId,
          summary: `${def.label} — operational loop transition`,
          metadata: {
            attemptId,
            operational_loop: true,
            cycleNumber: ctx.cycleNumber ?? 1,
            ...ctx.metadata,
          },
          facts: {
            lastTransitionKey: ctx.transitionKey,
            lastTransitionAt: new Date().toISOString(),
            cycleNumber: ctx.cycleNumber ?? 1,
            ...(ctx.facts ?? {}),
          },
        });
        if (result.error) {
          return { effect, success: false, error: result.error };
        }
        return { effect, success: true, detail: result.instanceId };
      }

      case "rules_engine": {
        const outcomes: string[] = [];
        for (const ruleSetKey of def.ruleSetKeys) {
          try {
            const evaluation = await evaluateRuleSet(
              {
                ruleSetKey,
                facts: {
                  studentId: ctx.studentId,
                  schoolId: ctx.schoolId,
                  transitionKey: ctx.transitionKey,
                  fromStage: def.fromStage,
                  toStage: def.toStage,
                  ...(ctx.facts ?? {}),
                },
                entityType: "student",
                entityId: ctx.studentId,
                schoolId: ctx.schoolId,
                organizationId: ctx.organizationId ?? undefined,
                actorUserId: ctx.actorUserId ?? undefined,
              },
              { persist: { supabase }, publishEvent: { supabase, actorId: ctx.actorUserId ?? undefined } }
            );
            outcomes.push(`${ruleSetKey}:${evaluation.primaryOutcome?.outcomeKey ?? "evaluated"}`);
          } catch (err) {
            outcomes.push(`${ruleSetKey}:skipped`);
          }
        }
        return { effect, success: true, detail: outcomes.join(", ") };
      }

      case "jag_profile": {
        await syncStudentPlatformRelationships(supabase, ctx.studentId);
        return {
          effect,
          success: true,
          detail: `Profile sync — sections: ${def.profileSections.join(", ")}`,
        };
      }

      case "paj_journey": {
        const journey = await getPajJourneyByStudent(supabase, ctx.studentId);
        if (!journey) {
          return { effect, success: true, detail: "No PAJ journey — skipped" };
        }
        const pajEventType =
          ctx.transitionKey === "enrollment_to_scheduling"
            ? "learning.placement.completed"
            : ctx.transitionKey === "evidence_to_progress"
              ? "learning.mastery.updated"
              : ctx.transitionKey === "progress_to_parent_communication"
                ? "learning.competency.advanced"
                : null;
        if (!pajEventType) {
          return { effect, success: true, detail: "No PAJ event mapping — skipped" };
        }
        await publishPajEvent(supabase, {
          eventType: pajEventType,
          journeyId: journey.id,
          studentId: ctx.studentId,
          schoolId: ctx.schoolId,
          organizationId: ctx.organizationId ?? undefined,
          actorUserId: ctx.actorUserId ?? undefined,
          payload: {
            transitionKey: ctx.transitionKey,
            toStage: def.toStage,
            attemptId,
          },
        });
        return { effect, success: true, detail: `${pajEventType}:${journey.id}` };
      }

      case "platform_audit": {
        await writePlatformAudit(supabase, {
          schoolId: ctx.schoolId,
          module: "work",
          entityType: "student",
          entityId: ctx.studentId,
          actionType: "operational_loop_transition",
          summary: `${def.label} completed`,
          workflowKey: OPERATIONAL_LOOP_WORKFLOW_KEY,
          actorUserId: ctx.actorUserId,
          metadata: {
            operational_loop: true,
            attemptId,
            transitionKey: ctx.transitionKey,
            fromStage: def.fromStage,
            toStage: def.toStage,
            instanceId,
            status: "completed",
            sideEffectsPending: false,
            cycleNumber: ctx.cycleNumber ?? 1,
            relatedEntityType: ctx.relatedEntityType,
            relatedEntityId: ctx.relatedEntityId,
            ...ctx.metadata,
          },
          afterState: { stage: def.toStage, transitionKey: ctx.transitionKey },
        });
        return { effect, success: true };
      }

      case "mission_control": {
        await createMissionControlItem(supabase, {
          schoolId: ctx.schoolId,
          module: def.nextWorkModule,
          itemType: def.nextWorkItemType,
          title: def.nextWorkTitle,
          body: `Operational loop advanced to ${def.toStage.replace(/_/g, " ")}`,
          entityType: "student",
          entityId: ctx.studentId,
          href: def.nextWorkHref,
          severity: "normal",
          metadata: {
            operational_loop: true,
            transitionKey: ctx.transitionKey,
            attemptId,
          },
        });
        return { effect, success: true, detail: def.nextWorkHref };
      }

      case "executive_intelligence": {
        await writePlatformAudit(supabase, {
          schoolId: ctx.schoolId,
          module: "executive",
          entityType: "student",
          entityId: ctx.studentId,
          actionType: "operational_loop_intelligence_signal",
          summary: `Loop transition ${ctx.transitionKey} — executive intelligence updated`,
          actorUserId: ctx.actorUserId,
          isSystemEvent: true,
          metadata: {
            operational_loop: true,
            transitionKey: ctx.transitionKey,
            toStage: def.toStage,
            attemptId,
          },
        });
        return { effect, success: true };
      }

      default:
        return { effect, success: false, error: "Unknown side effect" };
    }
  } catch (err) {
    return {
      effect,
      success: false,
      error: err instanceof Error ? err.message : "Side effect failed",
    };
  }
}

async function resolveCurrentStage(
  supabase: AuthClient,
  studentId: string
): Promise<{ stage: string | null; instanceId?: string; cycleNumber: number }> {
  const instance = await getActiveWorkflowInstance(supabase, {
    domain: "sis",
    entityType: "student",
    entityId: studentId,
  });

  if (!instance) {
    return { stage: null, cycleNumber: 1 };
  }

  const facts = (instance.facts ?? {}) as { cycleNumber?: number };
  return {
    stage: instance.current_state_key,
    instanceId: instance.id,
    cycleNumber: facts.cycleNumber ?? 1,
  };
}

async function recordFailedTransition(
  supabase: AuthClient,
  ctx: LoopTransitionContext,
  def: ReturnType<typeof getLoopTransition>,
  attemptId: string,
  sideEffects: LoopSideEffectResult[],
  errors: string[]
) {
  await publishEvent(
    {
      eventType: "jag.operational_loop.transition_failed",
      entityType: "student",
      entityId: ctx.studentId,
      schoolId: ctx.schoolId,
      organizationId: ctx.organizationId ?? undefined,
      actorId: ctx.actorUserId ?? undefined,
      payload: { transitionKey: ctx.transitionKey, attemptId, errors },
    },
    { persist: { supabase }, recordAudit: true }
  ).catch(() => undefined);

  await writePlatformAudit(supabase, {
    schoolId: ctx.schoolId,
    module: "work",
    entityType: "student",
    entityId: ctx.studentId,
    actionType: "operational_loop_transition_failed",
    summary: `${def.label} failed — recoverable`,
    workflowKey: OPERATIONAL_LOOP_WORKFLOW_KEY,
    actorUserId: ctx.actorUserId,
    metadata: {
      operational_loop: true,
      attemptId,
      transitionKey: ctx.transitionKey,
      status: "failed",
      errors,
      sideEffects,
      recoverable: true,
      ...ctx.metadata,
    },
  });

  await createMissionControlItem(supabase, {
    schoolId: ctx.schoolId,
    module: "mission_control",
    itemType: "failed_automation",
    title: `Operational loop transition failed — ${def.label}`,
    body: errors.join("; ") || "Side effects incomplete",
    entityType: "student",
    entityId: ctx.studentId,
    href: "/dashboard/executive?view=operational-loop",
    severity: "high",
    metadata: { attemptId, transitionKey: ctx.transitionKey, recoverable: true },
  });
}

/**
 * Execute an operational loop transition — coordinates platform side effects
 * without duplicating domain business logic.
 */
export async function executeOperationalLoopTransition(
  supabase: AuthClient,
  input: LoopTransitionContext
): Promise<LoopTransitionResult> {
  const def = getLoopTransition(input.transitionKey);
  const attemptId = randomUUID();
  const { stage: currentStage, cycleNumber: existingCycle } = await resolveCurrentStage(
    supabase,
    input.studentId
  );

  const cycleNumber =
    input.transitionKey === "billing_to_scheduling_cycle"
      ? existingCycle + 1
      : (input.cycleNumber ?? existingCycle);

  const ctx: LoopTransitionContext = { ...input, cycleNumber };
  const sideEffects: LoopSideEffectResult[] = [];
  const errors: string[] = [];

  for (const effect of SIDE_EFFECT_ORDER) {
    const result = await runSideEffect(
      supabase,
      effect,
      ctx,
      def,
      attemptId,
      currentStage,
      undefined
    );
    sideEffects.push(result);
    if (!result.success && result.error) {
      errors.push(`${effect}: ${result.error}`);
    }
  }

  const criticalEffects: TransitionSideEffect[] = ["platform_audit"];
  const criticalFailed = sideEffects.some(
    (s) => criticalEffects.includes(s.effect) && !s.success
  );

  if (criticalFailed || errors.length > 0) {
    await recordFailedTransition(supabase, ctx, def, attemptId, sideEffects, errors);
    return {
      success: false,
      transitionKey: input.transitionKey,
      fromStage: def.fromStage,
      toStage: def.toStage,
      attemptId,
      sideEffects,
      errors,
      recoverable: true,
    };
  }

  return {
    success: true,
    transitionKey: input.transitionKey,
    fromStage: def.fromStage,
    toStage: def.toStage,
    attemptId,
    sideEffects,
    errors: [],
    recoverable: false,
  };
}

/** Fire multiple transitions in sequence (e.g. enrollment handoff). */
export async function executeOperationalLoopTransitionChain(
  supabase: AuthClient,
  transitions: LoopTransitionContext[]
): Promise<LoopTransitionResult[]> {
  const results: LoopTransitionResult[] = [];
  for (const t of transitions) {
    const result = await executeOperationalLoopTransition(supabase, t);
    results.push(result);
    if (!result.success) break;
  }
  return results;
}

