import doc98Import from "@/lib/platform/ulr/catalog/structured-literacy/competencies/foundational-pa/doc98-import.json";
import {
  buildPaAiMetadata,
  buildPaCompetencyFromImport,
  PA_DOMAIN_KEY,
  PA_STRAND_KEY,
  type Doc98CompetencyImport,
} from "@/lib/platform/ulr/catalog/structured-literacy/shared-defaults";
import { SL_GENERATED_ATOMIC_SKILLS } from "@/lib/platform/ulr/catalog/structured-literacy/competencies/all-libraries";
import type { UlrAtomicSkillDefinition } from "@/lib/platform/ulr/types";

/** Document 98 §7 — PA atomic skill placeholders. */
export function buildSlPaAtomicSkillsFromDoc98(): UlrAtomicSkillDefinition[] {
  const records = doc98Import.competencies as Doc98CompetencyImport[];
  const skills: UlrAtomicSkillDefinition[] = [];

  for (const record of records) {
    for (const ref of record.futureAtomicSkillRefs) {
      skills.push({
        skillKey: ref.key,
        competencyKey: record.competencyKey,
        learningDomainKey: PA_DOMAIN_KEY,
        strandKey: PA_STRAND_KEY,
        subStrandKey: record.subStrandKey,
        title: ref.title,
        description: `Doc 98 placeholder atomic skill for ${record.title}`,
        version: "1.0.0",
        status: "draft",
        prerequisites: [],
        relatedSkills: [],
        nextSkills: [],
        crossDomainLinks: [],
        difficulty: "foundational",
        masteryCriteria: "≥ 4/5 trials per Doc 51 probe threshold (placeholder)",
        evidenceTypes: record.evidenceTypes.slice(0, 2),
        minimumEvidenceCount: 2,
        assessmentMethods: record.assessmentMethods.slice(0, 1),
        aiMetadata: buildPaAiMetadata(),
        portfolioEligible: false,
        transcriptEligible: false,
        metadata: {
          placeholder: true,
          documentRef: "DOCUMENT-98",
          libraryKey: doc98Import.libraryKey,
        },
      });
    }
  }

  return skills;
}

export const SL_PA_ATOMIC_SKILLS = buildSlPaAtomicSkillsFromDoc98();

/** All SL atomic skills — Doc 98 PA placeholders + generated library placeholders. */
export const SL_ALL_ATOMIC_SKILLS: UlrAtomicSkillDefinition[] = [
  ...SL_PA_ATOMIC_SKILLS,
  ...SL_GENERATED_ATOMIC_SKILLS,
];

import {
  getAllUlrCompetencies,
  getUlrRelationships,
} from "@/lib/platform/ulr/registry/registry";
import type { ValidateUlrKeysInput, ValidateUlrKeysResult } from "@/lib/platform/ulr/types";
import { isValidUlrCompetencyKey, isValidUlrSkillKey } from "@/lib/platform/ulr/version";
import {
  isKnownUlrCompetencyKey,
  isKnownUlrSkillKey,
} from "@/lib/platform/ulr/registry/registry";

export interface UlrValidationIssue {
  code:
    | "unknown_competency_key"
    | "unknown_skill_key"
    | "invalid_competency_key_format"
    | "invalid_skill_key_format"
    | "prerequisite_cycle";
  message: string;
}

export interface UlrValidationResult {
  ok: boolean;
  issues: UlrValidationIssue[];
}

/** Validate competency and skill keys against the ULR registry. */
export function validateUlrKeys(input: ValidateUlrKeysInput): ValidateUlrKeysResult {
  const unknownCompetencyKeys: string[] = [];
  const unknownSkillKeys: string[] = [];

  for (const key of input.competencyKeys ?? []) {
    if (!isKnownUlrCompetencyKey(key)) unknownCompetencyKeys.push(key);
  }

  for (const key of input.skillKeys ?? []) {
    if (!isKnownUlrSkillKey(key)) unknownSkillKeys.push(key);
  }

  return {
    ok: unknownCompetencyKeys.length === 0 && unknownSkillKeys.length === 0,
    unknownCompetencyKeys,
    unknownSkillKeys,
  };
}

/** Detect prerequisite cycles in published competency graph (ULR-2). */
export function validateUlrPrerequisiteGraph(): UlrValidationResult {
  const issues: UlrValidationIssue[] = [];
  const graph = new Map<string, string[]>();

  for (const competency of getAllUlrCompetencies()) {
    graph.set(competency.competencyKey, [
      ...competency.prerequisiteCompetencyKeys,
      ...getUlrRelationships({
        sourceKey: competency.competencyKey,
        relationshipType: "prerequisite",
      }).map((rel) => rel.targetKey),
    ]);
  }

  const visiting = new Set<string>();
  const visited = new Set<string>();

  function dfs(node: string, stack: string[]): void {
    if (visiting.has(node)) {
      issues.push({
        code: "prerequisite_cycle",
        message: `Prerequisite cycle detected: ${[...stack, node].join(" -> ")}`,
      });
      return;
    }
    if (visited.has(node)) return;
    visiting.add(node);
    for (const next of graph.get(node) ?? []) {
      dfs(next, [...stack, node]);
    }
    visiting.delete(node);
    visited.add(node);
  }

  for (const key of graph.keys()) dfs(key, []);

  for (const competency of getAllUlrCompetencies()) {
    if (!isValidUlrCompetencyKey(competency.competencyKey)) {
      issues.push({
        code: "invalid_competency_key_format",
        message: `Invalid competency key format: ${competency.competencyKey}`,
      });
    }
  }

  return { ok: issues.length === 0, issues };
}

export function validateUlrRegistry(): UlrValidationResult {
  const prerequisiteResult = validateUlrPrerequisiteGraph();
  return prerequisiteResult;
}

import type { createAuthClient } from "@/lib/supabase/server-auth";
import { computeStudentSuccessScore } from "@/lib/ssis/score";
import { getStudentSchedule } from "@/lib/scheduling/queries";
import { getStudentMeetings } from "@/lib/instruction/meetings";
import { getFamilyFinancialProfile } from "@/lib/finance/family-center";
import { getParentEngagementSummary } from "@/lib/ssis/engagement";
import { getPortalTasks } from "@/lib/portal/tasks";
import { getUnreadNotificationCount } from "@/lib/portal/notifications";
import { getParentDeadlines } from "@/lib/compliance/deadlines";

type AuthClient = Awaited<ReturnType<typeof createAuthClient>>;

export interface PortalStudentSummary {
  id: string;
  first_name: string;
  last_name: string;
  program: string | null;
  grade_level: string | null;
  school_id: string;
  family_id: string | null;
  successScore: Awaited<ReturnType<typeof computeStudentSuccessScore>>;
  todaySessions: number;
  upcomingMeetings: number;
  attendanceAlert: boolean;
  medicalAlerts: number;
  documentsNeeded: number;
}

export async function getLinkedStudentsForPortal(supabase: AuthClient, userId: string) {
  const { data: links } = await supabase.from("student_family_link").select("student_id").eq("user_id", userId);
  const { data: guardians } = await supabase.from("guardians").select("family_id").eq("user_id", userId);
  const familyIds = guardians?.map((g) => g.family_id) ?? [];

  let familyStudents: { id: string }[] = [];
  if (familyIds.length) {
    const { data } = await supabase.from("students").select("id").in("family_id", familyIds);
    familyStudents = data ?? [];
  }

  const ids = [...new Set([...(links?.map((l) => l.student_id) ?? []), ...familyStudents.map((s) => s.id)])];
  if (!ids.length) return [];

  const { data: students } = await supabase
    .from("students")
    .select("id, first_name, last_name, program, grade_level, school_id, family_id, lifecycle_stage")
    .in("id", ids)
    .eq("lifecycle_stage", "active");

  return students ?? [];
}

export async function getParentDashboardData(supabase: AuthClient, userId: string) {
  const students = await getLinkedStudentsForPortal(supabase, userId);
  const today = new Date().toISOString().split("T")[0];
  const tomorrow = new Date(Date.now() + 86400000).toISOString().split("T")[0];

  const summaries: PortalStudentSummary[] = [];
  let combinedBalance = 0;
  let combinedCredits = 0;

  for (const student of students) {
    const [score, schedule, meetings, attendanceRes, medicalRes, docsRes] = await Promise.all([
      computeStudentSuccessScore(supabase, student.id),
      getStudentSchedule(student.id),
      getStudentMeetings(supabase, student.id),
      supabase
        .from("student_attendance_records")
        .select("status")
        .eq("student_id", student.id)
        .eq("attendance_date", today),
      supabase
        .from("ssis_medical_expiry_alerts")
        .select("id")
        .eq("student_id", student.id)
        .eq("is_resolved", false),
      supabase
        .from("student_documents")
        .select("id")
        .eq("student_id", student.id)
        .eq("status", "active")
        .or("expires_at.is.null,expires_at.lt." + today),
    ]);

    const todaySessions =
      (schedule.sessions ?? []).filter((s) => {
        const d = (s as { scheduled_start?: string }).scheduled_start?.split("T")[0];
        return d === today;
      }).length +
      (schedule.services ?? []).filter((s) => {
        const d = (s as { scheduled_at?: string }).scheduled_at?.split("T")[0];
        return d === today;
      }).length;

    const upcomingMeetings = meetings.filter(
      (m) => m.parent_visible !== false && m.scheduled_at && m.scheduled_at >= new Date().toISOString()
    ).length;

    summaries.push({
      ...student,
      successScore: score,
      todaySessions,
      upcomingMeetings,
      attendanceAlert: (attendanceRes.data ?? []).some((a) => ["absent", "tardy"].includes(a.status)),
      medicalAlerts: medicalRes.data?.length ?? 0,
      documentsNeeded: docsRes.data?.length ?? 0,
    });
  }

  const familyIds = [...new Set(students.map((s) => s.family_id).filter(Boolean))] as string[];
  const financialProfiles = [];
  for (const familyId of familyIds) {
    const profile = await getFamilyFinancialProfile(supabase, familyId);
    if (profile?.account) {
      combinedBalance += Number(profile.account.balance ?? 0);
      combinedCredits += Number(profile.account.credit_balance ?? 0);
      financialProfiles.push(profile);
    }
  }

  const studentIds = students.map((s) => s.id);
  const [tasks, deadlines, unreadNotifications, engagement] = await Promise.all([
    getPortalTasks(supabase, userId, studentIds),
    getParentDeadlines(supabase, userId, studentIds),
    getUnreadNotificationCount(supabase, userId),
    students[0] ? getParentEngagementSummary(supabase, students[0].id) : Promise.resolve(null),
  ]);

  return {
    students: summaries,
    financial: { combinedBalance, combinedCredits, profiles: financialProfiles },
    tasks,
    deadlines,
    unreadNotifications,
    engagement,
    dateRange: { today, tomorrow },
  };
}

