  });

  it("generates full depreciation schedule", () => {
    const asset = assets.addAsset({
      name: "Vehicle",
      acquisitionDate: "2025-01-01",
      acquisitionCost: 30000,
      salvageValue: 0,
      usefulLifeYears: 3,
