    expect(kpis.expenseGrowth).toBeCloseTo(6.7, 0); // (1.6M-1.5M)/1.5M
  });

  it("calculates grant dependency", () => {
    const kpis = exec.calculateKPIs(snapshot);
    expect(kpis.grantDependency).toBeCloseTo(15, 0); // 300K/2M = 15%
  });

